<script setup>
import { ref, reactive, onMounted } from 'vue';
import { ElMessage, ElMessageBox } from 'element-plus';
const props=defineProps({api:{type:Function,required:true}});
const rows=ref([]),allClasses=ref([]),total=ref(0),page=ref(1),pageSize=ref(20),loading=ref(false),busy=ref(false);
const query=reactive({q:'',isActive:'',term:''}); const editOpen=ref(false), editId=ref(null), form=reactive({name:'',term:'',description:''});
const activeTab=ref('classes'), unassignedPageSize=ref(20), memberPageSize=ref(20);
const unassigned=ref([]),unassignedPage=ref(1),unassignedTotal=ref(0),unassignedQuery=ref('');
const membersOpen=ref(false),selectedClass=ref(null),members=ref([]),memberPage=ref(1),memberTotal=ref(0),memberQuery=ref(''),overview=ref(null);
const assignOpen=ref(false),candidates=ref([]),selectedIds=ref([]),candidateQuery=ref(''),scope=ref('unassigned');
const body=(value,method='POST')=>({method,body:JSON.stringify(value)});
async function loadClassOptions(){allClasses.value=(await props.api('/api/admin/classes?all=true')).rows||[];}
async function load(){loading.value=true;try{const p=new URLSearchParams({page:String(page.value),pageSize:String(pageSize.value),...query});const data=await props.api('/api/admin/classes?'+p);rows.value=data.rows||[];total.value=data.total||0;page.value=data.page||1;}catch(e){ElMessage.error(e.message);}finally{loading.value=false;}}
async function loadUnassigned(){try{const p=new URLSearchParams({page:String(unassignedPage.value),pageSize:String(unassignedPageSize.value),q:unassignedQuery.value});const data=await props.api('/api/admin/classes/unassigned/students?'+p);unassigned.value=data.rows||[];unassignedTotal.value=data.total||0;unassignedPage.value=data.page||1;}catch(e){ElMessage.error(e.message);}}
function search(){page.value=1;load();}
function edit(row){editId.value=row?.id||null;Object.assign(form,{name:row?.name||'',term:row?.term||'',description:row?.description||''});editOpen.value=true;}
async function save(){if(busy.value)return;busy.value=true;try{await props.api(editId.value?`/api/admin/classes/${editId.value}`:'/api/admin/classes',body(form,editId.value?'PUT':'POST'));editOpen.value=false;ElMessage.success('班级已保存');await Promise.all([load(),loadClassOptions()]);}catch(e){ElMessage.error(e.message);}finally{busy.value=false;}}
async function toggle(row){try{await ElMessageBox.confirm(`确定${row.isActive?'停用':'启用'}“${row.name}”？`,'确认操作',{type:'warning'});await props.api(`/api/admin/classes/${row.id}/status`,body({isActive:!row.isActive},'PATCH'));await Promise.all([load(),loadClassOptions()]);}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(e.message);}}
async function loadMembers(){if(!selectedClass.value)return;try{const p=new URLSearchParams({page:String(memberPage.value),pageSize:String(memberPageSize.value),q:memberQuery.value});const data=await props.api(`/api/admin/classes/${selectedClass.value.id}/members?`+p);members.value=data.rows||[];memberTotal.value=data.total||0;memberPage.value=data.page||1;}catch(e){ElMessage.error(e.message);}}
async function loadOverview(){try{overview.value=await props.api(`/api/admin/classes/${selectedClass.value.id}/overview`);}catch(e){ElMessage.error(e.message);}}
function showMembers(row){selectedClass.value=row;membersOpen.value=true;memberPage.value=1;memberQuery.value='';overview.value=null;loadMembers();loadOverview();}
async function remove(row){try{await ElMessageBox.confirm(`将 ${row.displayName} 移出班级？历史记录仍保留。`,'确认移出',{type:'warning'});await props.api(`/api/admin/classes/${selectedClass.value.id}/members/${row.id}`,{method:'DELETE'});await Promise.all([loadMembers(),loadOverview(),load(),loadUnassigned()]);}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(e.message);}}
async function loadCandidates(){try{const p=new URLSearchParams({q:candidateQuery.value,scope:scope.value});candidates.value=(await props.api(`/api/admin/classes/${selectedClass.value.id}/candidates?`+p)).rows||[];}catch(e){ElMessage.error(e.message);}}
function assign(row){selectedClass.value=row;selectedIds.value=[];scope.value='unassigned';candidateQuery.value='';assignOpen.value=true;loadCandidates();}
async function addMembers(){if(!selectedIds.value.length||busy.value)return;busy.value=true;try{const data=await props.api(`/api/admin/classes/${selectedClass.value.id}/members`,body({studentIds:selectedIds.value}));ElMessage.success(`已分配 ${data.assigned} 人`);assignOpen.value=false;await Promise.all([load(),loadUnassigned(),membersOpen.value?loadMembers():Promise.resolve(),membersOpen.value?loadOverview():Promise.resolve()]);}catch(e){ElMessage.error(e.message);}finally{busy.value=false;}}
onMounted(()=>{load();loadUnassigned();loadClassOptions().catch(e=>ElMessage.error(e.message));});
</script>
<template>
<section class="classes-page"><header class="heading"><div><h1>班级分组</h1><p>管理班级与学生归属，学生历史记录会保留。</p></div><div><el-button @click="load();loadUnassigned()">刷新</el-button><el-button type="primary" @click="edit()">新建班级</el-button></div></header>
<el-tabs v-model="activeTab" class="class-tabs"><el-tab-pane label="班级列表" name="classes"><div class="class-pane"><el-form inline @submit.prevent="search"><el-form-item><el-input v-model="query.q" placeholder="搜索班级名或说明" clearable @clear="search"/></el-form-item><el-form-item><el-select v-model="query.isActive" clearable placeholder="全部状态" style="width:130px" @change="search"><el-option label="启用" value="1"/><el-option label="停用" value="0"/></el-select></el-form-item><el-form-item><el-select v-model="query.term" clearable placeholder="全部学期" style="width:160px" @change="search"><el-option v-for="term in [...new Set(allClasses.map(c=>c.term).filter(Boolean))]" :key="term" :label="term" :value="term"/></el-select></el-form-item><el-button native-type="submit" type="primary">查询</el-button></el-form>
<el-table v-loading="loading" :data="rows" height="100%"><el-table-column prop="name" label="班级" min-width="150"/><el-table-column prop="term" label="学期/届次" min-width="120"/><el-table-column prop="memberCount" label="学生人数" width="95"/><el-table-column label="状态" width="80"><template #default="{row}"><el-tag :type="row.isActive?'success':'info'">{{row.isActive?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column prop="description" label="说明" min-width="150"/><el-table-column label="操作" min-width="260" fixed="right"><template #default="{row}"><el-button link type="primary" @click="showMembers(row)">成员</el-button><el-button link type="primary" @click="assign(row)">添加学生</el-button><el-button link type="primary" @click="edit(row)">编辑</el-button><el-button link :type="row.isActive?'danger':'success'" @click="toggle(row)">{{row.isActive?'停用':'启用'}}</el-button></template></el-table-column></el-table><div class="pager"><span>共 {{total}} 个班级</span><el-pagination v-model:current-page="page" v-model:page-size="pageSize" :page-sizes="[10,20,50]" :total="total" layout="sizes, prev, pager, next" @size-change="page=1;load()" @current-change="load"/></div>
</div></el-tab-pane><el-tab-pane label="未分班学生" name="unassigned"><div class="class-pane"><el-form inline @submit.prevent="unassignedPage=1;loadUnassigned()"><el-form-item><el-input v-model="unassignedQuery" placeholder="搜索学生" clearable @clear="unassignedPage=1;loadUnassigned()"/></el-form-item><el-button native-type="submit">查询</el-button></el-form><el-table :data="unassigned" height="100%"><el-table-column prop="displayName" label="姓名"/><el-table-column prop="studentId" label="学号"/><el-table-column prop="username" label="账号"/></el-table><div class="pager"><span>共 {{unassignedTotal}} 人</span><el-pagination v-model:current-page="unassignedPage" v-model:page-size="unassignedPageSize" :page-sizes="[10,20,50]" :total="unassignedTotal" layout="sizes, prev, pager, next" @size-change="unassignedPage=1;loadUnassigned()" @current-change="loadUnassigned"/></div>
</div></el-tab-pane></el-tabs>
<el-dialog v-model="editOpen" :title="editId?'编辑班级':'新建班级'" width="min(560px,94vw)"><el-form label-position="top" @submit.prevent="save"><el-form-item label="班级名称"><el-input v-model="form.name" maxlength="80"/></el-form-item><el-form-item label="学期/届次"><el-input v-model="form.term" maxlength="40"/></el-form-item><el-form-item label="说明"><el-input v-model="form.description" type="textarea" maxlength="300"/></el-form-item><el-button type="primary" native-type="submit" :loading="busy">保存</el-button></el-form></el-dialog>
<el-dialog v-model="membersOpen" :title="`${selectedClass?.name || ''} · 班级成员`" width="min(960px,96vw)"><el-collapse v-if="overview"><el-collapse-item title="班级概况"><p>成员 {{overview.metrics.memberCount}} 人 · 今日活跃 {{overview.metrics.activeToday}} 人 · 近 7 天 {{overview.metrics.sessionsWeek}} 次（{{overview.metrics.minutesWeek}} 分钟） · 平均 {{overview.metrics.averageSpeed}} 字/分 · 准确率 {{overview.metrics.averageAccuracy}}%</p><div class="overview"><div><strong>班级任务</strong><p v-for="t in overview.tasks" :key="t.id">{{t.title}} · {{t.completedCount}}/{{t.targetCount}} 人完成</p><p v-if="!overview.tasks.length">暂无任务</p></div><div><strong>需要关注</strong><p v-for="s in overview.risks" :key="s.id">{{s.displayName}} · {{s.risk}}</p><p v-if="!overview.risks.length">暂无</p></div><div><strong>速度排行</strong><p v-for="s in overview.ranking" :key="s.id">{{s.displayName}} · {{s.recentSpeed||0}} 字/分</p><p v-if="!overview.ranking.length">暂无</p></div></div></el-collapse-item></el-collapse><el-form inline @submit.prevent="memberPage=1;loadMembers()"><el-input v-model="memberQuery" placeholder="搜索成员" style="width:220px" clearable @clear="memberPage=1;loadMembers()"/><el-button native-type="submit">查询</el-button><el-button type="primary" @click="assign(selectedClass)">添加学生</el-button></el-form><el-table :data="members"><el-table-column prop="displayName" label="姓名"/><el-table-column prop="username" label="账号"/><el-table-column label="加入时间"><template #default="{row}">{{row.joinedAt?new Date(row.joinedAt).toLocaleDateString('zh-CN'):'—'}}</template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button link type="danger" @click="remove(row)">移出班级</el-button></template></el-table-column></el-table><div class="pager"><span>共 {{memberTotal}} 人</span><el-pagination v-model:current-page="memberPage" v-model:page-size="memberPageSize" :page-sizes="[10,20,50]" :total="memberTotal" layout="sizes,prev,pager,next" @size-change="memberPage=1;loadMembers()" @current-change="loadMembers"/></div></el-dialog>
<el-dialog v-model="assignOpen" :title="`添加学生至 ${selectedClass?.name||''}`" width="min(750px,96vw)"><p>已在其他班级的学生会调入当前班级，历史记录保留。</p><el-form inline @submit.prevent="loadCandidates"><el-input v-model="candidateQuery" placeholder="搜索姓名或账号" style="width:200px"/><el-select v-model="scope" style="width:140px" @change="loadCandidates"><el-option label="只看未分班" value="unassigned"/><el-option label="全部学生" value="all"/></el-select><el-button native-type="submit">查询</el-button></el-form><div><el-button link type="primary" @click="selectedIds=[...new Set([...selectedIds,...candidates.map(c=>c.id)])]">全选当前结果</el-button><el-button link @click="selectedIds=[]">清空已选</el-button></div><el-table :data="candidates" max-height="400"><el-table-column width="50"><template #default="{row}"><el-checkbox v-model="selectedIds" :value="row.id" :aria-label="`选择${row.displayName}`"/></template></el-table-column><el-table-column prop="displayName" label="姓名"/><el-table-column prop="username" label="账号"/><el-table-column prop="className" label="当前班级"/></el-table><template #footer><span>已选 {{selectedIds.length}} 人</span> <el-button @click="assignOpen=false">取消</el-button><el-button type="primary" :loading="busy" :disabled="!selectedIds.length" @click="addMembers">加入班级</el-button></template></el-dialog>
</section>
</template>
<style scoped>.heading{display:flex;justify-content:space-between;gap:16px;align-items:center;margin-bottom:24px}.heading h1{margin:0}.heading p{color:#6b7280}.pager{display:flex;justify-content:space-between;align-items:center;margin:20px 0 32px}.overview{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}.overview p{margin:8px 0}@media(max-width:700px){.heading{align-items:flex-start;flex-direction:column}.overview{grid-template-columns:1fr}}</style>
